// src/core/tokens.css
var tokens_default = '/**\n * F\xD3NDIKA \xB7 tokens de color\n * Fuente \xFAnica: Brand_kit_Fondika/02-color-y-tipografia (secci\xF3n "2. Paleta").\n * Exactamente 18 colores. No se agregan naranjas "deep" ni el degradado de marca:\n * esos viven en la secci\xF3n 4 del brandkit y quedan fuera de esta librer\xEDa por decisi\xF3n de producto.\n */\n:root {\n  /* Naranja */\n  --fdk-naranja-900: #ff9f19; /* primario */\n  --fdk-naranja-700: #ffb04d;\n  --fdk-naranja-500: #ffbe6f;\n  --fdk-naranja-300: #ffc884;\n  --fdk-naranja-100: #ffd29b;\n\n  /* Turquesa */\n  --fdk-turquesa-900: #0092a6; /* primario */\n  --fdk-turquesa-700: #02aab7;\n  --fdk-turquesa-500: #1ecad3;\n  --fdk-turquesa-300: #98d7dd;\n  --fdk-turquesa-100: #afe2e3;\n\n  /* Gris \u2014 negro solo */\n  --fdk-gris-900: #535659; /* primario \xB7 \xFAnico color v\xE1lido para cuerpo de texto */\n  --fdk-gris-700: #a7a8a9;\n  --fdk-gris-500: #b1b1b1;\n  --fdk-gris-300: #b9b9ba;\n  --fdk-gris-100: #dddddd;\n\n  /* Rojo de sistema \u2014 no es color de marca, es color de estado */\n  --fdk-rojo-900: #ad332b; /* error, borde, bot\xF3n destructivo */\n  --fdk-rojo-700: #c64a40;\n  --fdk-rojo-100: #ffeae6; /* fondo de alerta */\n\n  /* Alias sem\xE1nticos */\n  --fdk-brand: var(--fdk-naranja-900);\n  --fdk-ink: var(--fdk-gris-900);\n  --fdk-surface: #ffffff;\n  --fdk-border: var(--fdk-gris-300);\n  --fdk-danger: var(--fdk-rojo-900);\n\n  /*\n   * Niveles de Alert \u2014 copiados literal de Brand_kit_Fondika/03-design-system/assets/\n   * componentes.html (\xA7ALERTAS: .a-info/.a-exito/.a-alerta/.a-error). Alert usa SIEMPRE estos\n   * colores fijos (no son personalizables desde la API, a diferencia de Toast).\n   *\n   * Clasificaci\xF3n de estados de Rumbo \u2192 nivel (ver alert/nivel.ts):\n   *   Informaci\xF3n  \u2192 reposo, escuchando, pensando, cargando\n   *   Listo        \u2192 exito\n   *   Alerta ("Ten en cuenta") \u2192 alerta\n   *   Error ("No se pudo completar") \u2192 error\n   *   (sin-conexion usa el tratamiento neutro por defecto, fuera de componentes.html)\n   */\n  --fdk-alert-info-bg: var(--fdk-turquesa-100);\n  --fdk-alert-info-border: var(--fdk-turquesa-900);\n  --fdk-alert-exito-bg: var(--fdk-turquesa-100);\n  --fdk-alert-exito-border: var(--fdk-turquesa-900);\n  --fdk-alert-alerta-bg: var(--fdk-naranja-100);\n  /*\n   * Excepci\xF3n documentada: componentes.html usa `--deep-700 #ca5610` (naranja profundo) como\n   * borde de `.a-alerta`, un tono que vive en la secci\xF3n 4 (degradado) del brandkit y por eso\n   * normalmente queda fuera de esta librer\xEDa (ver cabecera de este archivo). Se reproduce aqu\xED,\n   * literal, s\xF3lo para que Alert sea fiel 1:1 al componente de referencia \u2014 no se usa en\n   * ning\xFAn otro lugar de la librer\xEDa.\n   */\n  --fdk-alert-alerta-border: #ca5610;\n  --fdk-alert-error-bg: var(--fdk-rojo-100);\n  --fdk-alert-error-border: var(--fdk-rojo-900);\n\n  /* Espaciado (subset de la escala del brandkit, base 4px) */\n  --fdk-sp-1: 4px;\n  --fdk-sp-2: 8px;\n  --fdk-sp-3: 12px;\n  --fdk-sp-4: 16px;\n  --fdk-sp-5: 24px;\n  --fdk-sp-6: 32px;\n\n  /* Forma y movimiento */\n  --fdk-radius-sm: 4px;\n  --fdk-radius-md: 8px;\n  --fdk-radius-lg: 16px;\n  --fdk-duration-base: 250ms;\n  --fdk-ease-out: cubic-bezier(.16,1,.3,1);\n\n  /* Sombras y foco \u2014 de Brand_kit_Fondika/03-design-system/assets/fondika-design-tokens.json */\n  --fdk-shadow-4: 0 16px 40px rgba(83,86,89,.18), 0 4px 8px rgba(83,86,89,.08);\n  --fdk-backdrop: rgb(0 0 0 / 45%);\n  --fdk-foco: 0 0 0 3px rgba(0,146,166,.40);\n\n  /*\n   * Botones de Modal \u2014 regla de estado de componentes.html: la superficie se desplaza hacia su\n   * propia tinta, 8% en hover y 12% al presionar; el color de la etiqueta nunca cambia.\n   */\n  --fdk-btn-primario-bg: var(--fdk-naranja-900);\n  --fdk-btn-primario-hover: #eb9217;\n  --fdk-btn-primario-activo: #e08c16;\n  --fdk-btn-secundario-hover: #f1f1f2;\n  --fdk-btn-secundario-activo: #eaebeb;\n  --fdk-btn-destructivo-bg: var(--fdk-rojo-900);\n  --fdk-btn-destructivo-hover: #b4433c;\n  --fdk-btn-destructivo-activo: #b74b44;\n\n  /* z-index \u2014 \xFAnica fuente, offsets fijos por capa */\n  --fdk-z-base: 9000;\n\n  --fdk-font: "Inter", "Helvetica Neue", Arial, sans-serif;\n  --fdk-font-display: "Outfit", "Futura", "Century Gothic", "Trebuchet MS", sans-serif;\n}\n\n@media (prefers-reduced-motion: reduce) {\n  :root { --fdk-duration-base: 0ms; }\n}\n';

// src/core/styles.ts
var injected = false;
function ensureStyles(extraCss = "") {
  if (typeof document === "undefined") return;
  if (!injected) {
    const style = document.createElement("style");
    style.setAttribute("data-fondika", "tokens");
    style.textContent = tokens_default;
    document.head.appendChild(style);
    injected = true;
  }
  if (extraCss && !document.querySelector(`style[data-fondika-css="${extraCss.length}"]`)) {
    const style = document.createElement("style");
    style.setAttribute("data-fondika-css", String(extraCss.length));
    style.textContent = extraCss;
    document.head.appendChild(style);
  }
}

// src/rumbo/rumbo.css
var rumbo_default = '/**\n * Animaciones de Rumbo \u2014 verbatim de Brand_kit_Fondika/04-personaje/assets/rumbo.html.\n * Ning\xFAn estado se mueve m\xE1s r\xE1pido que 1.4s salvo `cargando`. Reposo respira a 3.4s.\n */\n/*\n * position + z-index: Rumbo siempre pinta por encima del resto del contenido de su contenedor\n * (Alert, Toast, Modal, Overlay\u2026). Sus animaciones (salta, flota, sube, respira) mueven partes\n * del personaje fuera de su propia caja con `transform` \u2014 sin esto, un hermano en el flujo\n * normal puede quedar "encima" en el orden de pintado y tapar justo la parte que se mueve\n * (t\xEDpicamente la de arriba: Vida, o la cabeza en el salto de \xE9xito).\n */\n.fdk-rumbo { display: block; overflow: visible; position: relative; z-index: 1; }\n\n@keyframes fdk-respira { 0%,100% { transform: translateY(0) scaleY(1); } 50% { transform: translateY(-2.5px) scaleY(1.02); } }\n@keyframes fdk-flota { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-5px); } }\n@keyframes fdk-onda { 0% { r: 10; opacity: .55; } 100% { r: 30; opacity: 0; } }\n@keyframes fdk-piensa { 0%,100% { opacity: .25; transform: translateY(0); } 50% { opacity: 1; transform: translateY(-3px); } }\n@keyframes fdk-sube-punto { 0% { opacity: .15; transform: translateY(6px); } 50% { opacity: 1; transform: translateY(0); } 100% { opacity: .15; transform: translateY(-4px); } }\n@keyframes fdk-salta { 0%,100% { transform: translateY(0) scale(1,1); } 22% { transform: translateY(0) scale(1.08,.9); } 45% { transform: translateY(-14px) scale(.96,1.06); } 70% { transform: translateY(0) scale(1.05,.95); } }\n@keyframes fdk-sube-vida { 0%,100% { transform: translateY(0); } 45% { transform: translateY(-12px); } }\n@keyframes fdk-cae { 0%,100% { transform: rotate(-4deg) translateY(4px); } 50% { transform: rotate(-6deg) translateY(6px); } }\n@keyframes fdk-aleja { 0%,100% { transform: translate(0,0); opacity: 1; } 50% { transform: translate(5px,4px); opacity: .75; } }\n@keyframes fdk-pulso { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-4px); } }\n\n.fdk-rumbo__respira { animation: fdk-respira 3.4s ease-in-out infinite; transform-origin: 60px 98px; }\n.fdk-rumbo__flota { animation: fdk-flota 3.4s ease-in-out infinite; }\n.fdk-rumbo__onda { animation: fdk-onda 2.2s ease-out infinite; }\n.fdk-rumbo__o2 { animation-delay: 1.1s; }\n.fdk-rumbo__p { animation: fdk-piensa 1.5s ease-in-out infinite; }\n.fdk-rumbo__p2 { animation-delay: .2s; }\n.fdk-rumbo__p3 { animation-delay: .4s; }\n.fdk-rumbo__c { animation: fdk-sube-punto 1.6s ease-in-out infinite; }\n.fdk-rumbo__c2 { animation-delay: .15s; }\n.fdk-rumbo__c3 { animation-delay: .3s; }\n.fdk-rumbo__c4 { animation-delay: .45s; }\n.fdk-rumbo__salta { animation: fdk-salta 1.8s cubic-bezier(.3,0,.3,1) infinite; transform-origin: 60px 98px; }\n.fdk-rumbo__sube { animation: fdk-sube-vida 1.8s cubic-bezier(.3,0,.3,1) infinite; }\n.fdk-rumbo__cae { animation: fdk-cae 2.6s ease-in-out infinite; transform-origin: 60px 98px; }\n.fdk-rumbo__aleja { animation: fdk-aleja 2.6s ease-in-out infinite; }\n.fdk-rumbo__alerta-signo { animation: fdk-pulso 1.4s ease-in-out infinite; }\n\n@media (prefers-reduced-motion: reduce) {\n  .fdk-rumbo * { animation: none !important; }\n}\n';

export {
  ensureStyles,
  rumbo_default
};
